CHUNK = '        # admitted by profile_extensions. They are never auto-loaded from prose scope.\n        extensions = self.config.get("profile_extensions", {})\n        if not isinstance(extensions, dict):\n            raise StandardConfigurationError("profile_extensions must be an object")\n        extended_rule_ids: set[str] = set()\n        for profile_id, ids in extensions.items():\n            if profile_id not in self.profiles:\n                raise StandardConfigurationError(\n                    f"profile_extensions references unknown profile {profile_id!r}"\n                )\n            if not isinstance(ids, list) or not all(isinstance(x, str) for x in ids):\n                raise StandardConfigurationError(\n                    f"profile_extensions[{profile_id!r}] must be a list of rule ids"\n                )\n            for rid in ids:\n                if rid not in self.local_rules:\n                    raise StandardConfigurationError(\n                        f"profile_extensions[{profile_id!r}] references non-local rule {rid!r}"\n                    )\n                extended_rule_ids.add(rid)\n\n        orphan_local = [\n            r.id\n            for r in self.local_rules.values()\n            if r.specializes is None and r.id not in extended_rule_ids\n        ]\n        if orphan_local:\n            raise StandardConfigurationError(\n                "Local rules must either explicitly specialize a shared rule or be "\n                f"listed in profile_extensions. Orphans: {sorted(orphan_local)}"\n            )\n\n        # Validate language overlay mapping.\n        overlays = self.config.get("language_overlays", {})\n        if not isinstance(overlays, dict):\n            raise StandardConfigurationError("language_overlays must be an object")\n        for language, profile_id in overlays.items():\n            if not isinstance(language, str) or not isinstance(profile_id, str):\n                raise StandardConfigurationError(\n                    "language_overlays must map strings to profile ids"\n                )\n            if profile_id not in self.profiles:\n                raise StandardConfigurationError(\n                    f"Language {language!r} references missing overlay profile {profile_id!r}"\n                )\n\n        default_profile = self.config.get("default_profile", "general")\n        if default_profile != "general":\n            raise StandardConfigurationError(\n                "v1 default_profile must remain \'general\'; the fallback is kernel-only"\n            )\n\n        if self.config.get("path_resolution", "deferred") != "deferred":\n            raise StandardConfigurationError(\n                "v1 path_resolution must remain \'deferred\'; no path resolver is authorized"\n            )\n\n'
